// Tile colors
export const COLORS = {
  RED: { name: 'red', hex: '#e74c3c' },
  BLUE: { name: 'blue', hex: '#3498db' },
  BLACK: { name: 'black', hex: '#2c3e50' },
  ORANGE: { name: 'orange', hex: '#e67e22' }
};

// Message for flip reveal (24 characters)
const MESSAGE = "WILL YOU BE MY VALENTINE";

// Create 24 tiles for the puzzle
export const createInitialTiles = () => {
  const tiles = [
    // Run 1: Red 1-2-3-4
    { id: 1, number: 1, color: COLORS.RED },
    { id: 2, number: 2, color: COLORS.RED },
    { id: 3, number: 3, color: COLORS.RED },
    { id: 4, number: 4, color: COLORS.RED },

    // Run 2: Blue 5-6-7-8
    { id: 5, number: 5, color: COLORS.BLUE },
    { id: 6, number: 6, color: COLORS.BLUE },
    { id: 7, number: 7, color: COLORS.BLUE },
    { id: 8, number: 8, color: COLORS.BLUE },

    // Run 3: Black 9-10-11-12
    { id: 9, number: 9, color: COLORS.BLACK },
    { id: 10, number: 10, color: COLORS.BLACK },
    { id: 11, number: 11, color: COLORS.BLACK },
    { id: 12, number: 12, color: COLORS.BLACK },

    // Run 4: Orange 2-3-4-5
    { id: 13, number: 2, color: COLORS.ORANGE },
    { id: 14, number: 3, color: COLORS.ORANGE },
    { id: 15, number: 4, color: COLORS.ORANGE },
    { id: 16, number: 5, color: COLORS.ORANGE },

    // Group 1: All 6s (Red, Blue, Black, Orange)
    { id: 17, number: 6, color: COLORS.RED },
    { id: 18, number: 6, color: COLORS.BLACK },
    { id: 19, number: 6, color: COLORS.ORANGE },

    // Group 2: All 9s (Red, Blue, Orange) - Blue 9 doesn't exist yet
    { id: 20, number: 9, color: COLORS.RED },
    { id: 21, number: 9, color: COLORS.BLUE },
    { id: 22, number: 9, color: COLORS.ORANGE },

    // Extra tiles to make 24
    { id: 23, number: 1, color: COLORS.BLUE },
    { id: 24, number: 1, color: COLORS.BLACK },
  ];

  // Assign letters from message to each tile
  tiles.forEach((tile, index) => {
    tile.letter = MESSAGE[index] || '?';
  });

  return shuffleArray([...tiles]);
};

// Fisher-Yates shuffle
function shuffleArray(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

// Check if tiles form a valid run (3+ consecutive numbers, same color)
export function isValidRun(tiles) {
  if (tiles.length < 3) return false;

  // All tiles must be same color
  const color = tiles[0].color.name;
  if (!tiles.every(t => t.color.name === color)) return false;

  // Sort by number and check consecutive
  const sorted = [...tiles].sort((a, b) => a.number - b.number);
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i].number !== sorted[i - 1].number + 1) return false;
  }

  return true;
}

// Check if tiles form a valid group (3-4 same numbers, different colors)
export function isValidGroup(tiles) {
  if (tiles.length < 3 || tiles.length > 4) return false;

  // All tiles must have same number
  const number = tiles[0].number;
  if (!tiles.every(t => t.number === number)) return false;

  // All tiles must have different colors
  const colors = tiles.map(t => t.color.name);
  const uniqueColors = new Set(colors);
  if (uniqueColors.size !== tiles.length) return false;

  return true;
}

// Validate a single row - tiles must be consecutive (no gaps) and form valid meld
export function validateRow(rowTiles) {
  // Filter out null slots
  const tiles = rowTiles.filter(t => t !== null);

  // Need at least 3 tiles
  if (tiles.length < 3) return false;

  // Check for gaps - tiles should be in consecutive slots
  let firstTileIndex = -1;
  let lastTileIndex = -1;

  for (let i = 0; i < rowTiles.length; i++) {
    if (rowTiles[i] !== null) {
      if (firstTileIndex === -1) firstTileIndex = i;
      lastTileIndex = i;
    }
  }

  // Check no gaps between first and last tile
  for (let i = firstTileIndex; i <= lastTileIndex; i++) {
    if (rowTiles[i] === null) return false; // Gap found
  }

  // Validate as run or group
  return isValidRun(tiles) || isValidGroup(tiles);
}

// Check if entire grid is valid (all rows have valid melds)
export function validateGrid(grid) {
  // grid is 4 rows x 6 cols
  for (let row = 0; row < 4; row++) {
    if (!validateRow(grid[row])) {
      return { valid: false, invalidRow: row };
    }
  }
  return { valid: true, invalidRow: -1 };
}

// Check if all tiles are placed
export function allTilesPlaced(grid, totalTiles) {
  let count = 0;
  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 6; col++) {
      if (grid[row][col] !== null) count++;
    }
  }
  return count === totalTiles;
}
