import React, { useState } from 'react';
import './valentines.css';
import Grid from './Grid';
import Rack from './Rack';
import Tile from './Tile';
import Confetti from './Confetti';
import { createInitialTiles, validateGrid, allTilesPlaced } from './gameLogic';

const GAME_STATES = {
  START: 'start',
  PLAYING: 'playing',
  CHECKING: 'checking',
  WON: 'won',
  FLIPPING: 'flipping',
  QUESTION: 'question',
  YES: 'yes',
};

const Valentines = () => {
  const [gameState, setGameState] = useState(GAME_STATES.START);
  const [rackTiles, setRackTiles] = useState([]);
  const [grid, setGrid] = useState(Array(4).fill(null).map(() => Array(6).fill(null)));
  const [allTiles, setAllTiles] = useState([]);
  const [invalidRows, setInvalidRows] = useState([]);
  const [noButtonPosition, setNoButtonPosition] = useState({ x: 0, y: 0 });
  const [errorMessage, setErrorMessage] = useState('');

  const startGame = () => {
    const tiles = createInitialTiles();
    setAllTiles(tiles);
    setRackTiles(tiles);
    setGrid(Array(4).fill(null).map(() => Array(6).fill(null)));
    setInvalidRows([]);
    setErrorMessage('');
    setGameState(GAME_STATES.PLAYING);
  };

  const handleDropToGrid = (tileId, targetRow, targetCol, sourceType, sourceRow, sourceCol) => {
    // Check if target slot is already occupied
    if (grid[targetRow][targetCol] !== null) {
      return; // Can't drop on occupied slot
    }

    let tile;
    let newRackTiles = [...rackTiles];
    let newGrid = grid.map(row => [...row]);

    if (sourceType === 'rack') {
      // Moving from rack to grid
      tile = rackTiles.find(t => t.id === tileId);
      newRackTiles = rackTiles.filter(t => t.id !== tileId);
    } else {
      // Moving from grid to grid
      tile = grid[sourceRow][sourceCol];
      newGrid[sourceRow][sourceCol] = null;
    }

    newGrid[targetRow][targetCol] = tile;
    setRackTiles(newRackTiles);
    setGrid(newGrid);
    setInvalidRows([]);
    setErrorMessage('');
  };

  const handleDropToRack = (e) => {
    e.preventDefault();
    const tileId = parseInt(e.dataTransfer.getData('tileId'), 10);
    const sourceType = e.dataTransfer.getData('sourceType');

    if (sourceType !== 'grid') return; // Only accept tiles from grid

    const sourceRow = parseInt(e.dataTransfer.getData('sourceRow'), 10);
    const sourceCol = parseInt(e.dataTransfer.getData('sourceCol'), 10);

    const tile = grid[sourceRow][sourceCol];
    const newGrid = grid.map(row => [...row]);
    newGrid[sourceRow][sourceCol] = null;

    setGrid(newGrid);
    setRackTiles([...rackTiles, tile]);
    setInvalidRows([]);
    setErrorMessage('');
  };

  const handleCheckSolution = () => {
    // First check if all tiles are placed
    if (!allTilesPlaced(grid, allTiles.length)) {
      setErrorMessage('Place all tiles on the board first!');
      return;
    }

    // Validate each row
    const result = validateGrid(grid);

    if (result.valid) {
      // WIN!
      setGameState(GAME_STATES.FLIPPING);
      setTimeout(() => {
        setGameState(GAME_STATES.QUESTION);
      }, 3000);
    } else {
      // Show which rows are invalid
      const invalid = [];
      for (let i = 0; i < 4; i++) {
        const rowTiles = grid[i].filter(t => t !== null);
        if (rowTiles.length > 0) {
          const { validateRow } = require('./gameLogic');
          if (!validateRow(grid[i])) {
            invalid.push(i);
          }
        }
      }
      setInvalidRows(invalid);
      setErrorMessage('Some rows are not valid melds. Each row needs a run (same color, consecutive numbers) or a group (same number, different colors).');
    }
  };

  const handleYes = () => {
    setGameState(GAME_STATES.YES);
  };

  const handleNo = () => {
    // Make the No button run away!
    setNoButtonPosition({
      x: (Math.random() - 0.5) * 400,
      y: (Math.random() - 0.5) * 300
    });
  };

  // Get all tiles from grid in order for flip animation
  const getGridTilesForFlip = () => {
    const tiles = [];
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 6; col++) {
        if (grid[row][col]) {
          tiles.push(grid[row][col]);
        }
      }
    }
    return tiles;
  };

  return (
    <div className="valentines">
      {gameState === GAME_STATES.START && (
        <div className="valentines__start">
          <h1 className="valentines__title">Yuna's Rummikub Challenge</h1>
          <p className="valentines__subtitle">Can you solve this puzzle?</p>
          <button className="valentines__play-btn" onClick={startGame}>
            Play
          </button>
        </div>
      )}

      {gameState === GAME_STATES.PLAYING && (
        <div className="valentines__game">
          <h2 className="valentines__game-title">Arrange the tiles!</h2>
          <p className="valentines__instructions">
            Each row must be a valid meld: a <strong>run</strong> (3+ consecutive numbers, same color)
            or a <strong>group</strong> (3-4 same numbers, different colors)
          </p>

          <Grid
            grid={grid}
            onDropToGrid={handleDropToGrid}
            invalidRows={invalidRows}
          />

          <div
            className="rack-drop-zone"
            onDragOver={(e) => e.preventDefault()}
            onDrop={handleDropToRack}
          >
            <Rack tiles={rackTiles} />
          </div>

          {errorMessage && (
            <p className="valentines__error">{errorMessage}</p>
          )}

          <button className="valentines__check-btn" onClick={handleCheckSolution}>
            Check Solution
          </button>
        </div>
      )}

      {(gameState === GAME_STATES.FLIPPING || gameState === GAME_STATES.QUESTION || gameState === GAME_STATES.YES) && (
        <div className="valentines__win">
          <Confetti type={gameState === GAME_STATES.YES ? 'hearts' : 'confetti'} />

          <div className="valentines__flip-container">
            {getGridTilesForFlip().map((tile, index) => (
              <div
                key={tile.id}
                className="valentines__flip-tile"
                style={{ animationDelay: `${index * 0.1}s` }}
              >
                <Tile tile={tile} isFlipped={true} />
              </div>
            ))}
          </div>

          {gameState === GAME_STATES.QUESTION && (
            <div className="valentines__question">
              <h1 className="valentines__question-text">
                Will you be my Valentine, Yuna?
              </h1>
              <div className="valentines__buttons">
                <button className="valentines__yes-btn" onClick={handleYes}>
                  Yes!
                </button>
                <button
                  className="valentines__no-btn"
                  onClick={handleNo}
                  style={{
                    transform: `translate(${noButtonPosition.x}px, ${noButtonPosition.y}px)`
                  }}
                >
                  No
                </button>
              </div>
            </div>
          )}

          {gameState === GAME_STATES.YES && (
            <div className="valentines__celebration">
              <h1 className="valentines__love-text">I Love You, Yuna!</h1>
              <div className="valentines__hearts">
                ❤️ 💕 💖 💗 💓 💝
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default Valentines;
