import React, { useEffect, useState } from 'react';

const Confetti = ({ type = 'confetti' }) => {
  const [particles, setParticles] = useState([]);

  useEffect(() => {
    const particleCount = type === 'hearts' ? 30 : 50;
    const newParticles = [];

    for (let i = 0; i < particleCount; i++) {
      newParticles.push({
        id: i,
        left: Math.random() * 100,
        delay: Math.random() * 3,
        duration: 3 + Math.random() * 2,
        size: type === 'hearts' ? 20 + Math.random() * 20 : 8 + Math.random() * 8,
        color: type === 'hearts'
          ? `hsl(${340 + Math.random() * 20}, 80%, 60%)`
          : `hsl(${Math.random() * 360}, 70%, 60%)`,
        rotation: Math.random() * 360,
      });
    }

    setParticles(newParticles);
  }, [type]);

  return (
    <div className="confetti-container">
      {particles.map(particle => (
        <div
          key={particle.id}
          className={`confetti-particle ${type === 'hearts' ? 'confetti-particle--heart' : ''}`}
          style={{
            left: `${particle.left}%`,
            animationDelay: `${particle.delay}s`,
            animationDuration: `${particle.duration}s`,
            fontSize: type === 'hearts' ? `${particle.size}px` : undefined,
            width: type !== 'hearts' ? `${particle.size}px` : undefined,
            height: type !== 'hearts' ? `${particle.size}px` : undefined,
            backgroundColor: type !== 'hearts' ? particle.color : undefined,
            color: type === 'hearts' ? particle.color : undefined,
            transform: `rotate(${particle.rotation}deg)`,
          }}
        >
          {type === 'hearts' && '❤️'}
        </div>
      ))}
    </div>
  );
};

export default Confetti;
