import React from 'react';
import Tile from './Tile';

const Slot = ({ row, col, tile, onDrop, onDragOver, isInvalid }) => {
  const handleDragOver = (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (onDragOver) onDragOver(row, col);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    const tileId = parseInt(e.dataTransfer.getData('tileId'), 10);
    const sourceType = e.dataTransfer.getData('sourceType');
    const sourceRow = parseInt(e.dataTransfer.getData('sourceRow'), 10);
    const sourceCol = parseInt(e.dataTransfer.getData('sourceCol'), 10);
    onDrop(tileId, row, col, sourceType, sourceRow, sourceCol);
  };

  return (
    <div
      className={`grid__slot ${tile ? 'grid__slot--filled' : ''} ${isInvalid ? 'grid__slot--invalid' : ''}`}
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    >
      {tile && (
        <Tile
          tile={tile}
          isFlipped={false}
          sourceType="grid"
          sourceRow={row}
          sourceCol={col}
        />
      )}
    </div>
  );
};

const Grid = ({ grid, onDropToGrid, invalidRows }) => {
  return (
    <div className="grid">
      {grid.map((row, rowIndex) => (
        <div key={rowIndex} className={`grid__row ${invalidRows.includes(rowIndex) ? 'grid__row--invalid' : ''}`}>
          {row.map((tile, colIndex) => (
            <Slot
              key={`${rowIndex}-${colIndex}`}
              row={rowIndex}
              col={colIndex}
              tile={tile}
              onDrop={onDropToGrid}
              isInvalid={invalidRows.includes(rowIndex)}
            />
          ))}
        </div>
      ))}
    </div>
  );
};

export default Grid;
