import React from 'react';
import Tile from './Tile';

const Rack = ({ tiles, onDragStart, onDragEnd, draggingTileId }) => {
  const handleDragOver = (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e) => {
    e.preventDefault();
    // Tiles can be dropped back to rack - handled by parent
  };

  return (
    <div
      className="rack"
      onDragOver={handleDragOver}
      onDrop={handleDrop}
      data-zone="rack"
    >
      <div className="rack__label">Your Tiles</div>
      <div className="rack__tiles">
        {tiles.map(tile => (
          <Tile
            key={tile.id}
            tile={tile}
            isFlipped={false}
            onDragStart={onDragStart}
            onDragEnd={onDragEnd}
            isDragging={draggingTileId === tile.id}
          />
        ))}
      </div>
    </div>
  );
};

export default Rack;
