import React from 'react';

const Tile = ({ tile, isFlipped, onDragStart, onDragEnd, isDragging, sourceType = 'rack', sourceRow, sourceCol }) => {
  const handleDragStart = (e) => {
    e.dataTransfer.setData('tileId', tile.id.toString());
    e.dataTransfer.setData('sourceType', sourceType);
    if (sourceType === 'grid') {
      e.dataTransfer.setData('sourceRow', sourceRow.toString());
      e.dataTransfer.setData('sourceCol', sourceCol.toString());
    }
    e.dataTransfer.effectAllowed = 'move';
    if (onDragStart) onDragStart(tile.id);
  };

  const handleDragEnd = (e) => {
    if (onDragEnd) onDragEnd();
  };

  return (
    <div
      className={`tile ${isFlipped ? 'tile--flipped' : ''} ${isDragging ? 'tile--dragging' : ''}`}
      draggable={!isFlipped}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      style={{ '--tile-color': tile.color.hex }}
    >
      <div className="tile__inner">
        <div className="tile__front">
          <span className="tile__number" style={{ color: tile.color.hex }}>
            {tile.number}
          </span>
        </div>
        <div className="tile__back">
          <span className="tile__letter">{tile.letter}</span>
        </div>
      </div>
    </div>
  );
};

export default Tile;
